static bool xelpDisplay13RenderDevice(IOPCIDevice *pci) {
    return (xelpSelectedProfile.family==XELP::Family::AlderLakeN ||
        xelpSelectedProfile.mobileDisplay13()) && xelpSelectedDevice(pci);
}
