  auto maximum=__atomic_load_n(&xelpForceWakeIRQ[3],__ATOMIC_RELAXED);
  while(ns>maximum && !__atomic_compare_exchange_n(&xelpForceWakeIRQ[3],&maximum,ns,false,__ATOMIC_RELAXED,__ATOMIC_RELAXED)) {}
