	tglObservePath(observedPort, nullptr, 6, true, r, output ? *reinterpret_cast<uint32_t *>(static_cast<uint8_t *>(output) + 0x38) : 0, __builtin_return_address(0));
	if (id == 5) tglDPCDPublish();
