	if (record[0] <= 16) {
		snprintf(historyKey, sizeof(historyKey), "TGLTrainingPort%uFirst%u", id, record[0]);
		IORegistryEntry::getRegistryRoot()->setProperty(historyKey, record, sizeof(record));
	}
